{
  "actions": [
    {
      "action": "Delete expired records before serving requests",
      "mechanism": "A monotonic five-minute deadline determines freshness; source failures never extend retention.",
      "implementation": "Stamp successful insertions with expiry. Schedule deletion and recheck expiry on every read. Return 503 when an expired record cannot be replaced.",
      "check": "With a fake clock and timed-out source, requests at five minutes return 503; the expired record is absent.",
      "risk": "Scheduler delays require read-time enforcement, not timer-only freshness checks."
    },
    {
      "action": "Make capacity enforcement atomic",
      "mechanism": "A single admission lock prevents concurrent insertions from exceeding the 100-record cache limit.",
      "implementation": "Under the lock, remove expired entries, then evict the least recently used entry before inserting at capacity. Failed fetches trigger no capacity eviction.",
      "check": "Race 150 distinct successful fetches: occupancy never exceeds 100. During failure-only traffic, unexpired entries remain until their deadlines.",
      "risk": "Least-recently-used eviction can discard valuable records during sequential scans."
    },
    {
      "action": "Bound source waits and suppress repeated failures",
      "mechanism": "Timeouts and a circuit breaker turn a slow-source outage into predictable, explicit responses.",
      "implementation": "Set a source timeout and failure threshold. While the breaker is open, serve only unexpired hits; return 503 with Retry-After for misses. Permit one recovery probe.",
      "check": "Inject sustained timeouts: misses finish within the configured timeout, open-state requests skip fetching, and expiration deletion continues.",
      "risk": "An excessive cooldown delays detection of source recovery."
    },
    {
      "action": "Cache only an approved public-record projection",
      "mechanism": "An explicit field allowlist excludes private data rather than trusting entire source payloads.",
      "implementation": "Request only approved public fields from a public-only endpoint; validate before admission. Reject unexpected fields without logging payloads. Return 502 if no valid cached record exists.",
      "check": "Inject an unexpected sensitive field: no payload is cached, returned, or logged, and an existing unexpired record remains unchanged.",
      "risk": "Projection may omit distinctions callers require; document the response schema."
    }
  ],
  "abstention_reason": ""
}
